import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsFile 是每仓库阈值配置，相对于进程的工作目录。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值从 thresholdsFile 读取；仓库没配或配置不可用时回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取 thresholdsFile 里的仓库阈值。
//
// 文件不存在、读不出来、内容不是 JSON 对象时返回 nil，调用方一律回退默认值。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsFile)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}
